// Blit into a caller-owned RGB565 buffer (chunk rendering), clipped.
static inline void blitSprite(uint16_t* buf, int bufW, int bufH,
                              const Sprite& s, int x, int y) {
  for (int sy = 0; sy < (int)s.h; ++sy) {
    int dy = y + sy;
    if (dy < 0 || dy >= bufH) continue;
    for (int sx = 0; sx < (int)s.w; ++sx) {
      int dx = x + sx;
      if (dx < 0 || dx >= bufW) continue;
      if (s.mask) {
        int bit = sy * s.w + sx;
        if (!(s.mask[bit >> 3] & (0x80 >> (bit & 7)))) continue;
      }
      buf[dy * bufW + dx] = s.pixels[sy * s.w + sx];
    }
  }
}

// Blit directly to the display (for overlays outside the chunk buffer).
static inline void blitSpriteToDisplay(ILI9341_GFX* d, const Sprite& s,
                                        int x, int y) {
  for (int sy = 0; sy < (int)s.h; ++sy) {
    int runStart = -1, runLen = 0;
    for (int sx = 0; sx <= (int)s.w; ++sx) {
      bool opaque = sx < (int)s.w;
      if (opaque && s.mask) {
        int bit = sy * s.w + sx;
        opaque = s.mask[bit >> 3] & (0x80 >> (bit & 7));
      }
      if (opaque) {
        if (runStart < 0) runStart = sx;
        runLen++;
      } else {
        if (runStart >= 0) {
          d->setWindow(x + runStart, y + sy, x + runStart + runLen - 1, y + sy);
          d->pushPixels((uint16_t*)&s.pixels[sy * s.w + runStart], runLen);
          runStart = -1;
          runLen = 0;
        }
      }
    }
  }
}
